#!/usr/bin/env python3\n\"\"\"\nAdaptive Strategies Live Test\n============================\nTest script for the new reactive trading system with:\n- Reactive confidence decay\n- Real-time market monitoring\n- Regime-aware strategy weighting\n- Data source risk mitigation\n\nUsage:\n    python test_adaptive_live.py --mode paper --symbols RELIANCE,HDFCBANK,ICICIBANK\n    python test_adaptive_live.py --mode live --symbols TCS,INFY --config config.json\n\"\"\"\n\nimport sys\nimport os\nimport argparse\nimport logging\nimport time\nimport json\nfrom datetime import datetime, timedelta\nfrom typing import List, Dict, Any\nimport pandas as pd\n\n# Add src to path\nsys.path.insert(0, os.path.join(os.path.dirname(__file__), 'src'))\n\nfrom src.strategies.adaptive_manager import AdaptiveStrategyManager\nfrom src.core.models import ScreenerSignal\nfrom src.screener.excel_screener import ExcelScreener\nfrom config.config_manager import ConfigManager\n\n\nclass AdaptiveTradingTest:\n    \"\"\"Test framework for adaptive trading strategies\"\"\"\n    \n    def __init__(self, mode: str = \"paper\", symbols: List[str] = None):\n        \"\"\"Initialize test framework\"\"\"\n        self.mode = mode\n        self.symbols = symbols or [\"RELIANCE.NS\", \"HDFCBANK.NS\", \"ICICIBANK.NS\", \"TCS.NS\"]\n        \n        # Setup logging\n        logging.basicConfig(\n            level=logging.INFO,\n            format='%(asctime)s | %(name)s | %(levelname)s | %(message)s',\n            handlers=[\n                logging.StreamHandler(),\n                logging.FileHandler(f'logs/adaptive_test_{datetime.now().strftime(\"%Y%m%d_%H%M\")}.log')\n            ]\n        )\n        \n        self.logger = logging.getLogger(__name__)\n        \n        # Initialize components\n        self.config_manager = ConfigManager()\n        self.adaptive_manager = AdaptiveStrategyManager()\n        self.screener = ExcelScreener()\n        \n        # Test tracking\n        self.test_results = []\n        self.start_time = datetime.now()\n        \n        self.logger.info(f\"Initialized adaptive trading test in {mode} mode\")\n        self.logger.info(f\"Testing symbols: {self.symbols}\")\n    \n    def run_test_cycle(self, duration_minutes: int = 60) -> None:\n        \"\"\"Run a complete test cycle\"\"\"\n        \n        self.logger.info(f\"Starting {duration_minutes}-minute test cycle\")\n        \n        end_time = datetime.now() + timedelta(minutes=duration_minutes)\n        cycle_count = 0\n        \n        try:\n            while datetime.now() < end_time:\n                cycle_count += 1\n                self.logger.info(f\"\\n{'='*60}\")\n                self.logger.info(f\"Test Cycle #{cycle_count} - {datetime.now().strftime('%H:%M:%S')}\")\n                self.logger.info(f\"{'='*60}\")\n                \n                # Run adaptive strategy evaluation for each symbol\n                for symbol in self.symbols:\n                    try:\n                        result = self._evaluate_symbol(symbol, cycle_count)\n                        self.test_results.append(result)\n                        \n                        # Log result\n                        if result['should_enter']:\n                            self.logger.warning(\n                                f\"🟢 ENTRY SIGNAL: {symbol} | \"\n                                f\"Strategy: {result['primary_strategy']} | \"\n                                f\"Confidence: {result['confidence']:.2f} | \"\n                                f\"Reason: {result['entry_reason']}\"\n                            )\n                        else:\n                            self.logger.info(\n                                f\"⚪ NO SIGNAL: {symbol} | \"\n                                f\"Reason: {result['entry_reason']}\"\n                            )\n                        \n                    except Exception as e:\n                        self.logger.error(f\"Error evaluating {symbol}: {e}\")\n                \n                # Display system status\n                self._display_system_status()\n                \n                # Wait before next cycle (1 minute intervals)\n                self.logger.info(f\"Waiting 60 seconds for next cycle...\")\n                time.sleep(60)\n                \n        except KeyboardInterrupt:\n            self.logger.info(\"\\nTest interrupted by user\")\n        \n        # Final summary\n        self._display_test_summary()\n    \n    def _evaluate_symbol(self, symbol: str, cycle: int) -> Dict[str, Any]:\n        \"\"\"Evaluate a single symbol using adaptive strategies\"\"\"\n        \n        # Create mock screener signal (in real implementation, this comes from Excel screener)\n        signal = self._create_mock_signal(symbol)\n        \n        # Evaluate using adaptive manager\n        decision = self.adaptive_manager.evaluate_trade_entry(signal)\n        \n        # Package result\n        result = {\n            'timestamp': datetime.now(),\n            'cycle': cycle,\n            'symbol': symbol,\n            'should_enter': decision.should_enter,\n            'confidence': decision.confidence,\n            'entry_reason': decision.entry_reason,\n            'selected_strategies': decision.selected_strategies,\n            'strategy_weights': decision.strategy_weights,\n            'primary_strategy': decision.selected_strategies[0] if decision.selected_strategies else None,\n            'market_context': decision.market_context,\n            'parameters': decision.parameters\n        }\n        \n        return result\n    \n    def _create_mock_signal(self, symbol: str) -> ScreenerSignal:\n        \"\"\"Create a mock screener signal for testing\"\"\"\n        \n        # In real implementation, this would come from Excel screener\n        # For testing, we'll create realistic signals\n        \n        import random\n        import yfinance as yf\n        \n        try:\n            # Get real market data\n            ticker = yf.Ticker(symbol)\n            data = ticker.history(period=\"5d\", interval=\"5m\")\n            \n            if data.empty:\n                raise Exception(\"No data available\")\n            \n            latest = data.iloc[-1]\n            prev = data.iloc[-2] if len(data) > 1 else latest\n            \n            current_price = float(latest['Close'])\n            prev_price = float(prev['Close'])\n            price_change_pct = ((current_price - prev_price) / prev_price) * 100\n            \n            # Create signal based on real price action\n            trend = \"BULLISH\" if price_change_pct > 0 else \"BEARISH\"\n            score = min(100, max(0, 50 + abs(price_change_pct) * 10))\n            \n            signal = ScreenerSignal(\n                symbol=symbol,\n                trend=trend,\n                score=score,\n                current_price=current_price,\n                volume=float(latest['Volume']),\n                timestamp=datetime.now()\n            )\n            \n            return signal\n            \n        except Exception as e:\n            self.logger.warning(f\"Could not fetch real data for {symbol}, using mock: {e}\")\n            \n            # Fallback to mock signal\n            return ScreenerSignal(\n                symbol=symbol,\n                trend=random.choice([\"BULLISH\", \"BEARISH\"]),\n                score=random.randint(30, 90),\n                current_price=random.uniform(100, 3000),\n                volume=random.randint(100000, 10000000),\n                timestamp=datetime.now()\n            )\n    \n    def _display_system_status(self) -> None:\n        \"\"\"Display current system status\"\"\"\n        \n        try:\n            # Market detector status\n            market_state = self.adaptive_manager.market_detector.get_current_market_state()\n            \n            self.logger.info(\"\\n📊 SYSTEM STATUS:\")\n            self.logger.info(f\"   Market Direction: {market_state.direction.value} ({market_state.confidence:.2f})\")\n            self.logger.info(f\"   Gap: {market_state.gap_type.value} ({market_state.gap_size_pct:.2f}%)\")\n            self.logger.info(f\"   Volatility: {market_state.volatility_regime.value}\")\n            self.logger.info(f\"   Momentum Score: {market_state.momentum_score:.1f}\")\n            \n            # Strategy weights\n            if hasattr(self.adaptive_manager, 'current_weights'):\n                self.logger.info(\"\\n⚖️ STRATEGY WEIGHTS:\")\n                for strategy, weight in self.adaptive_manager.current_weights.items():\n                    self.logger.info(f\"   {strategy}: {weight:.2f}\")\n            \n            # Confidence manager status\n            confidence_summary = self.adaptive_manager.confidence_manager.get_confidence_summary()\n            self.logger.info(f\"\\n🎯 CONFIDENCE: Tracking {confidence_summary['total_symbols']} symbols\")\n            \n            # Real-time monitor status\n            monitor_summary = self.adaptive_manager.market_detector.realtime_monitor.get_monitoring_summary()\n            self.logger.info(f\"\\n📡 MONITOR: {monitor_summary['monitored_symbols_count']} symbols, {monitor_summary['total_candles_processed']} candles\")\n            \n            # Data quality status\n            data_quality = self.adaptive_manager.market_detector.data_mitigator.get_data_quality_report()\n            self.logger.info(\"\\n🛡️ DATA QUALITY:\")\n            for source, metrics in data_quality['source_metrics'].items():\n                self.logger.info(f\"   {source}: {metrics['avg_latency_ms']:.0f}ms, {metrics['success_rate']:.1%} success\")\n        \n        except Exception as e:\n            self.logger.error(f\"Error displaying system status: {e}\")\n    \n    def _display_test_summary(self) -> None:\n        \"\"\"Display final test summary\"\"\"\n        \n        self.logger.info(\"\\n\" + \"=\"*80)\n        self.logger.info(\"🏁 TEST SUMMARY\")\n        self.logger.info(\"=\"*80)\n        \n        if not self.test_results:\n            self.logger.info(\"No test results to display\")\n            return\n        \n        df = pd.DataFrame(self.test_results)\n        \n        # Overall stats\n        total_evaluations = len(df)\n        total_signals = len(df[df['should_enter'] == True])\n        signal_rate = (total_signals / total_evaluations * 100) if total_evaluations > 0 else 0\n        \n        self.logger.info(f\"📈 Total Evaluations: {total_evaluations}\")\n        self.logger.info(f\"🎯 Entry Signals: {total_signals} ({signal_rate:.1f}%)\")\n        self.logger.info(f\"⏱️ Test Duration: {datetime.now() - self.start_time}\")\n        \n        # Signal breakdown by symbol\n        self.logger.info(\"\\n📊 SIGNALS BY SYMBOL:\")\n        symbol_stats = df.groupby('symbol')['should_enter'].agg(['count', 'sum']).reset_index()\n        symbol_stats['signal_rate'] = (symbol_stats['sum'] / symbol_stats['count'] * 100).round(1)\n        \n        for _, row in symbol_stats.iterrows():\n            self.logger.info(f\"   {row['symbol']}: {row['sum']}/{row['count']} ({row['signal_rate']}%)\")\n        \n        # Strategy breakdown\n        if total_signals > 0:\n            signals_df = df[df['should_enter'] == True]\n            strategy_counts = {}\n            \n            for _, row in signals_df.iterrows():\n                primary = row.get('primary_strategy')\n                if primary:\n                    strategy_counts[primary] = strategy_counts.get(primary, 0) + 1\n            \n            self.logger.info(\"\\n🎲 SIGNALS BY STRATEGY:\")\n            for strategy, count in sorted(strategy_counts.items(), key=lambda x: x[1], reverse=True):\n                pct = (count / total_signals * 100)\n                self.logger.info(f\"   {strategy}: {count} ({pct:.1f}%)\")\n        \n        # Average confidence\n        if total_signals > 0:\n            avg_confidence = df[df['should_enter'] == True]['confidence'].mean()\n            self.logger.info(f\"\\n🎯 Average Signal Confidence: {avg_confidence:.2f}\")\n        \n        # Save results to file\n        results_file = f\"test_results_{datetime.now().strftime('%Y%m%d_%H%M')}.json\"\n        try:\n            # Convert datetime objects to strings for JSON serialization\n            results_for_json = []\n            for result in self.test_results:\n                json_result = result.copy()\n                json_result['timestamp'] = result['timestamp'].isoformat()\n                results_for_json.append(json_result)\n            \n            with open(results_file, 'w') as f:\n                json.dump(results_for_json, f, indent=2, default=str)\n            \n            self.logger.info(f\"\\n💾 Results saved to: {results_file}\")\n        except Exception as e:\n            self.logger.error(f\"Error saving results: {e}\")\n\n\ndef main():\n    \"\"\"Main execution function\"\"\"\n    parser = argparse.ArgumentParser(description=\"Test Adaptive Trading Strategies\")\n    parser.add_argument(\"--mode\", choices=[\"paper\", \"live\"], default=\"paper\", \n                       help=\"Trading mode (default: paper)\")\n    parser.add_argument(\"--symbols\", type=str, \n                       help=\"Comma-separated list of symbols (e.g., RELIANCE.NS,TCS.NS)\")\n    parser.add_argument(\"--duration\", type=int, default=30,\n                       help=\"Test duration in minutes (default: 30)\")\n    parser.add_argument(\"--config\", type=str,\n                       help=\"Configuration file path\")\n    \n    args = parser.parse_args()\n    \n    # Parse symbols\n    symbols = None\n    if args.symbols:\n        symbols = [s.strip() for s in args.symbols.split(\",\")]\n        # Add .NS suffix if not present\n        symbols = [s if \".NS\" in s else f\"{s}.NS\" for s in symbols]\n    \n    print(f\"🚀 Starting Adaptive Trading Test\")\n    print(f\"   Mode: {args.mode}\")\n    print(f\"   Duration: {args.duration} minutes\")\n    print(f\"   Symbols: {symbols or 'Default set'}\")\n    print(\"\")\n    \n    # Create and run test\n    test = AdaptiveTradingTest(mode=args.mode, symbols=symbols)\n    test.run_test_cycle(duration_minutes=args.duration)\n\n\nif __name__ == \"__main__\":\n    main()"